let cols, rows;
let grid;
let cellSize = 20;
let shapes = ["circle", "triangle", "rect"];
let shapeMap = [];
let growthThreshold = 2;
let maxAge = 100; // 每个细胞存活周期

let mySize;
let seed = Math.random() * 999999;
let colors = [];
let colorbg;

function make2DArray(cols, rows) {
	let arr = new Array(cols);
	for (let i = 0; i < cols; i++) {
		arr[i] = new Array(rows);
	}
	return arr;
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	cols = floor(width / cellSize);
	rows = floor(height / cellSize);

	grid = make2DArray(cols, rows);
	shapeMap = make2DArray(cols, rows);

	// 初始化稀疏的“种子细胞”
	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			grid[i][j] = {
				alive: random() < 0.02, // 少量初始活细胞
				age: 0
			};
			shapeMap[i][j] = random(shapes);
		}
	}

	// frameRate(10);
	noStroke();
	colors = random(colorScheme).colors;
	colorbg = random(bgcolor)
	background(colorbg);
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

	background(str(colorbg) + "33");

	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			let cell = grid[i][j];

			if (cell.alive) {
				cell.age++;
				let x = i * cellSize;
				let y = j * cellSize;

				let c = color(random(colors));
				c.setAlpha(map(cell.age, 0, maxAge, 20, 100));
				fill(c);

				push();
				translate(x + cellSize / 2, y + cellSize / 2);
				let s = cellSize * map(cell.age, 0, maxAge, 0.2, 1);

				switch (shapeMap[i][j]) {
					case "circle":
						ellipse(0, 0, s);
						break;
					case "rect":
						rectMode(CENTER);
						rect(0, 0, s, s);
						break;
					case "triangle":
						let h = s * sqrt(3) / 2;
						triangle(
							0, -h / 2,
							-s / 2, h / 2,
							s / 2, h / 2
						);
						break;
				}
				pop();

				if (cell.age > maxAge) {
					cell.alive = false; // 死亡
				}
			}
		}
	}

	naturalGrowthUpdate();

  pop();
}

function naturalGrowthUpdate() {
	let newGrid = make2DArray(cols, rows);

	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			var cell = grid[i][j];
			let neighbors = countAliveNeighbors(i, j);

			let newCell = {
				...cell
			};

			if (!cell.alive && neighbors >= growthThreshold && random() < 0.1) {
				newCell.alive = true;
				newCell.age = 0;
			} else if (cell.alive) {
				newCell.alive = true;
				newCell.age = cell.age;
			}

			newGrid[i][j] = newCell;
		}
	}

	grid = newGrid;
}

function countAliveNeighbors(x, y) {
	let total = 0;
	for (let i = -1; i <= 1; i++) {
		for (let j = -1; j <= 1; j++) {
			let col = (x + i + cols) % cols;
			let row = (y + j + rows) % rows;
			if ((i !== 0 || j !== 0) && grid[col][row].alive) {
				total++;
			}
		}
	}
	return total;
}
